 function statePill(p){return pill(p.status==='Active'?(p.publishedAt?'Published in demo':'Approved baseline'):p.status==='Hidden'?'Paused':p.status==='Retired'?'Archived':p.status,p.status==='Draft'?'warn':'neutral');}
 function issue(o){if(o.cancelled)return {text:'Cancelled - review remedy',type:'warn',rank:100};if(o.hold)return {text:'Order on hold',type:'bad',rank:95};if(o.payment!=='Captured'&&o.payment!=='Pending')return {text:'Check payment outcome',type:'warn',rank:90};if(o.items.some(i=>i.quality==='Failed'))return {text:'Quality check failed',type:'bad',rank:92};const p=o.items.find(i=>i.parcel&&/failed|unknown|stale|returning/i.test(i.parcel.status));if(p)return {text:p.parcel.status,type:/failed/i.test(p.parcel.status)?'bad':'warn',rank:88};const support=S.state.cases.find(c=>c.order===o.id&&c.status!=='Resolved');if(support)return {text:support.type==='Damage'?'Damage claim open':'Customer request open',type:'bad',rank:85};const task=S.state.tasks.find(t=>t.record===o.id&&t.status!=='Resolved');if(task)return {text:task.title,type:'warn',rank:80};if(S.summary(o)!=='Delivered'&&o.due<window.StudioState.demoDate)return {text:'Past original promise',type:'bad',rank:75};if(o.payment==='Pending')return {text:'Confirm payment',type:'warn',rank:35};if(S.summary(o)==='Delivered')return {text:'No open issue',type:'neutral',rank:0};return {text:'On track',type:'neutral',rank:5};}
 const stops=['Placed','Payment','Ready to make','Printing','Framing','Quality check','Packed','Pickup booked','Shipped','Out for delivery','Delivered'];
